  2: { key:'piquant',      icon:'face-grimace',      label:'Gênant',      hint:'Mensonges, ex, défauts, jalousie. Ça révèle, rien de sexuel.' },
  3: { key:'tres_piquant', icon:'fire',              label:'Intime',      hint:'Registre allusif de fin de soirée, jamais explicite.' },
  4: { key:'sans_filtre',  icon:'fire-flame-curved', label:'Sans filtre', hint:'Explicite et frontal. Adultes consentants uniquement.', adult:true },
  // Ton 5 : aucune question de la banque. Les joueurs écrivent tout, l'hôte arbitre.
  // Ce n'est pas un « ton » au sens du contenu, mais ça se choisit au même endroit et
